// Content with portions generated by generative AI platform
package org.eclipse.kura.core.internal.linux.executor;

import static java.nio.charset.StandardCharsets.UTF_8;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.atMost;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.util.Optional;

import org.apache.commons.exec.CommandLine;
import org.apache.commons.exec.DefaultExecutor;
import org.apache.commons.exec.ExecuteWatchdog;
import org.apache.commons.exec.Executor;
import org.eclipse.kura.core.linux.executor.LinuxSignal;
import org.eclipse.kura.executor.Command;
import org.eclipse.kura.executor.CommandStatus;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

public class ProcessGroupCommandLineTest {

    private static final String SETSID = "/usr/bin/setsid";
    private static final String MISSING_EXECUTABLE = "/nonexistent/kura-missing-command";
    private static final int START_FAILURE_EXIT_VALUE = 1;
    private static final int COMMAND_TIMEOUT_SECONDS = 30;

    private final DefaultExecutor executor = mock(DefaultExecutor.class);
    private ExecutorUtil executorUtil;
    private Command command;
    private CommandStatus status;
    private CommandLine executedCommandLine;
    private ExecuteWatchdog configuredWatchdog;

    @Test
    public void privilegedCommandStartsInItsOwnProcessGroup() {
        givenProcessGroupLauncher(Optional.of(SETSID));
        givenCommand("ls", "-l");

        whenExecutedPrivileged();

        thenExecutedCommandLineIs(SETSID, "ls", "-l");
    }

    @Test
    public void privilegedShellCommandStartsInItsOwnProcessGroup() {
        givenProcessGroupLauncher(Optional.of(SETSID));
        givenCommand("ls -l | wc -l");
        givenExecutedInAShell();

        whenExecutedPrivileged();

        thenExecutedCommandLineIs(SETSID, "/bin/sh", "-c", "ls -l | wc -l");
    }

    @Test
    public void privilegedCommandStartsDirectlyWithoutSetsid() {
        givenProcessGroupLauncher(Optional.empty());
        givenCommand("ls", "-l");

        whenExecutedPrivileged();

        thenExecutedCommandLineIs("ls", "-l");
    }

    @Test
    public void privilegedCommandWithTimeoutUsesProcessGroupWatchdog() {
        givenProcessGroupLauncher(Optional.of(SETSID));
        givenCommand("ls", "-l");
        givenTimeout(COMMAND_TIMEOUT_SECONDS);

        whenExecutedPrivileged();

        thenConfiguredWatchdogIsProcessGroupWatchdog(true);
    }

    @Test
    public void unprivilegedCommandWithTimeoutKeepsPlainWatchdog() {
        givenProcessGroupLauncher(Optional.of(SETSID));
        givenCommand("ls", "-l");
        givenTimeout(COMMAND_TIMEOUT_SECONDS);

        whenExecutedUnprivileged();

        thenConfiguredWatchdogIsProcessGroupWatchdog(false);
    }

    @Test
    public void missingProgramIsReportedAsStartFailure() {
        givenProcessGroupLauncher(Optional.of(SETSID));
        givenCommand(MISSING_EXECUTABLE);

        whenExecutedPrivileged();

        thenCommandIsNotLaunched();
        thenExitCodeIs(START_FAILURE_EXIT_VALUE);
        thenErrorStreamContains("Failed to start command: ");
        thenErrorStreamContains(MISSING_EXECUTABLE);
    }

    @Test
    public void missingProgramOnSearchPathIsReportedAsStartFailure() {
        givenProcessGroupLauncher(Optional.of(SETSID));
        givenCommand("kura-missing-command");

        whenExecutedPrivileged();

        thenCommandIsNotLaunched();
        thenExitCodeIs(START_FAILURE_EXIT_VALUE);
        thenErrorStreamContains("No such file or directory");
    }

    private void givenProcessGroupLauncher(Optional<String> launcher) {
        this.executorUtil = new ExecutorUtil() {

            @Override
            protected Executor getExecutor() {
                return ProcessGroupCommandLineTest.this.executor;
            }

            @Override
            protected Optional<String> getProcessGroupLauncher() {
                return launcher;
            }
        };
        when(this.executor.getWorkingDirectory()).thenReturn(new File(System.getProperty("java.io.tmpdir")));
    }

    private void givenCommand(String... commandLine) {
        this.command = new Command(commandLine);
        this.command.setSignal(LinuxSignal.SIGTERM);
        this.command.setErrorStream(new ByteArrayOutputStream());
    }

    private void givenExecutedInAShell() {
        this.command.setExecuteInAShell(true);
    }

    private void givenTimeout(int seconds) {
        this.command.setTimeout(seconds);
    }

    private void whenExecutedPrivileged() {
        this.status = this.executorUtil.executePrivileged(this.command);
        captureExecution();
    }

    private void whenExecutedUnprivileged() {
        this.status = this.executorUtil.executeUnprivileged(this.command);
        captureExecution();
    }

    private void captureExecution() {
        final ArgumentCaptor<CommandLine> commandLineCaptor = ArgumentCaptor.forClass(CommandLine.class);
        final ArgumentCaptor<ExecuteWatchdog> watchdogCaptor = ArgumentCaptor.forClass(ExecuteWatchdog.class);
        try {
            verify(this.executor, atMost(1)).execute(commandLineCaptor.capture());
        } catch (IOException e) {
            throw new IllegalStateException(e);
        }
        verify(this.executor).setWatchdog(watchdogCaptor.capture());
        this.executedCommandLine = commandLineCaptor.getAllValues().isEmpty() ? null : commandLineCaptor.getValue();
        this.configuredWatchdog = watchdogCaptor.getValue();
    }

    private void thenExecutedCommandLineIs(String executable, String... arguments) {
        assertEquals(executable, this.executedCommandLine.getExecutable());
        assertArrayEquals(arguments, this.executedCommandLine.getArguments());
    }

    private void thenConfiguredWatchdogIsProcessGroupWatchdog(boolean expected) {
        assertEquals(expected, this.configuredWatchdog instanceof ProcessGroupWatchdog);
    }

    private void thenCommandIsNotLaunched() {
        try {
            verify(this.executor, never()).execute(any(CommandLine.class));
        } catch (IOException e) {
            throw new IllegalStateException(e);
        }
    }

    private void thenExitCodeIs(int expected) {
        assertEquals(expected, this.status.getExitStatus().getExitCode());
    }

    private void thenErrorStreamContains(String expected) {
        final String errorOutput = new String(((ByteArrayOutputStream) this.status.getErrorStream()).toByteArray(),
                UTF_8);
        assertTrue("Error stream was: " + errorOutput, errorOutput.contains(expected));
    }
}
